<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\Review;use App\Services\ReviewModerationService;use Illuminate\Http\Request;
class ReviewController extends Controller
{public function index(Request $r){$reviews=Review::with(['product','user'])->when($r->filled('q'),function($q)use($r){$t='%'.trim($r->q).'%';$q->where(fn($x)=>$x->where('content','like',$t)->orWhereHas('product',fn($p)=>$p->where('name','like',$t))->orWhereHas('user',fn($u)=>$u->where('name','like',$t)));})->when($r->filled('status'),fn($q)=>$q->where('status',$r->status))->when($r->filled('rating'),fn($q)=>$q->where('rating',$r->rating))->latest()->paginate(20)->withQueryString();return view('admin.reviews.index',compact('reviews'));}public function show(Review $review){$review->load(['product','user','orderItem.order']);return view('admin.reviews.show',compact('review'));}public function moderate(Request $r,Review $review,ReviewModerationService $service){$d=$r->validate(['status'=>'required|in:approved,rejected,hidden','note'=>'nullable|string|max:500']);$service->transition($review,$d['status'],$r->user(),$d['note']??null);return back()->with('success','Đã cập nhật review.');}}
